class SubATask(TextGenerationTask):
    system_prompt: str = "A"
    def generate_prompt(self, input: str) -> "Prompt":
        return Prompt(system_prompt=self.system_prompt, formatted_prompt=input)

class SubBTask(TextGenerationTask):
    system_prompt: str = "B"
    def generate_prompt(self, input: str) -> "Prompt":
        return Prompt(system_prompt=self.system_prompt, formatted_prompt=input)

