def test_pipeline_process_batch_generations_skips_empty_outputs() -> None:
    pipeline = Pipeline(generator=DummyLLM(task=TextGenerationTask()))

    batch_generations = [
        [
            LLMOutput(
                model_name="dummy",
                prompt_used="dummy",
                raw_output="dummy",
                parsed_output=None,
            ),
            LLMOutput(
                model_name="dummy",
                prompt_used="dummy",
                raw_output="dummy",
                parsed_output={"generations": "dummy"},
            ),
        ]
    ]
    processed_generations = pipeline._process_batch_generations(
        batch_generations=batch_generations, shuffle_before_labelling=False
    )

    assert processed_generations == [
        {
            "generation_model": ["dummy", "dummy"],
            "generation_prompt": ["dummy", "dummy"],
            "raw_generation_responses": ["dummy", "dummy"],
            "generations": ["dummy"],
